(()=>{let visible=false;const trigger=()=>document.querySelector('[data-action="favorites"]');async function open(){const button=trigger();if(!button||!window.orbitDesktop?.showFavorites)return;const r=button.getBoundingClientRect(),result=await window.orbitDesktop.showFavorites({right:r.right,bottom:r.bottom});if(!result?.ok)toast(result?.error||'Unable to open favorites.');}function close(){return window.orbitDesktop?.closeFavorites();}
 document.addEventListener('click',event=>{if(event.target.closest('[data-action="favorites"]')){if(visible)close();else open();}});document.addEventListener('pointerdown',event=>{if(visible&&!event.target.closest('[data-action="favorites"]'))close();});document.addEventListener('keydown',event=>{if(visible&&event.key==='Escape'){event.preventDefault();close();}});window.addEventListener('resize',()=>{if(visible)open();});window.addEventListener('DOMContentLoaded',()=>{trigger()?.setAttribute('aria-haspopup','dialog');trigger()?.setAttribute('aria-expanded','false');window.orbitDesktop?.onFavoritesVisibility(value=>{visible=value;trigger()?.setAttribute('aria-expanded',String(value));});window.orbitDesktop?.onNotice(message=>toast(message));});window.OrbitFavorites=Object.freeze({open,close});
})();
